from save_review import save
save(1336,{2:'切割喷灯是星际战士使用的笨重热熔工具，有效作用距离极短，几乎只能处理贴近灯口的目标。'},notes={2:'删除原译附加的“短小无力”感叹，英文无对应。'},terms=[('Cutter Torches','切割喷灯')])
save(1337,{2:'变色龙伪装篷布由轻薄、坚韧的感光变色织物制成，能够呈现周围环境的外观。每块配发尺寸为5米见方，也可相互钩接，用来遮蔽兰德速攻艇、犀牛装甲车，乃至整座营地。'},terms=[('Cameleoline Tarpaulin','变色龙伪装篷布')],title='变色龙伪装篷布 Cameleoline Tarpaulin')
save(1338,{2:'基因贤者伊尔泽克隶属于杰里科疆域阿基里斯远征中的机械修会部队。他合成的渗透涂剂，利用了多数泰伦生物嗅觉感受器灵敏的特点：从兵虫类生物提取关键的信息素，掩盖涂用者的生物特征。目前的配方只针对达贡虫巢舰队的化学感受器，如何为其他舰队配制同类涂剂，仍完全未知。星际战士将它涂在动力盔甲上后，多数泰伦生物便不会将他识别为敌人，使其相对自如地穿过虫群密布的地区。但若靠近更聪明、感知更敏锐的突触生物或先锋生物，伪装就可能败露，引来虫群围攻。',4:'使用者必须身处阿斯塔特动力盔甲等环境密封装备中，涂剂才能奏效。只要不太靠近泰伦生物，这种生物特征伪装就能使他不引起对应虫巢舰队的注意，近乎“隐形”。一旦被任何泰伦生物识破，或主动攻击舰队中的生物，他便会暴露给视线范围内的所有泰伦。当然，虫巢暴君等具有灵能的生物很少会被这类伪装骗过。'},notes={2:'enamel在此为涂覆装甲的伪装涂剂，不按通常陶瓷工艺称珐琅；原渗透珐琅保留对照。essential是关键的信息素，不是基本分类。'},terms=[('Infiltriol','渗透涂剂'),('Iyrzek','伊尔泽克')],title='渗透涂剂 Infiltriol')
save(1339,{2:'跳跃背包是一种背负式装置，内置涡轮或喷气推进器，动力强得足以将穿着动力盔甲的使用者送上空中。',5:'跳跃背包源自古老的标准建造模板（STC）技术。顶部进气口将空气送入喷气系统，再由涡轮叶片排出，产生升力。将全副武装的星际战士推上天空需要极大功率，因此即使有动力盔甲能量线圈辅助，背包仍需独立供给燃料。通常使用十来次后，就必须补充燃料或弃置。',7:'Heresy-era Jump Pack 荷鲁斯之乱时期的跳跃背包',9:'它能大幅提升战士的机动性，使其快速穿越战场、跃过障碍，直接扑入近战。使用者从低空飞行器跃下时，轰鸣的发动机也能减缓下降速度，使其相对安全地以纵深打击方式直接投入交锋。',14:'Mk.IV 马克西姆型——由穿着 Mk.IV 动力盔甲的星际战士使用。这一特殊设计采用单个主推进器，并配有较小的机动喷口。',22:'鸦型跳跃背包——暗鸦守卫使用。它在战鹰型基础上改进，加入精密的矢量推力组件，使跳跃距离更远、落点更精准。',28:'迷影型跳跃背包——荷鲁斯之乱期间，黑暗天使炎翼使用。',38:'翔猎跳跃套具——翔猎禁军使用。',44:'飞翼跳跃背包——圣血天使的圣血守卫使用。',47:'The Korvidine Pinions 渡鸦翼羽'},terms=[('Jump Pack','跳跃背包'),('Corvid Pattern Jump Pack','鸦型跳跃背包'),('Heavy Jump Pack','重型跳跃背包'),('Enigmatus Pattern Jump Pack','迷影型跳跃背包'),('Valkyris Pattern','瓦尔基里型'),('Venatari Jump Harness','翔猎跳跃套具'),('Warhawk Pattern','战鹰型'),('Winged Jump Pack','飞翼跳跃背包'),('The Korvidine Pinions','渡鸦翼羽')])
save(1340,{2:'星际战士侦察小队需要隐秘部署，又无法使用传送或空降舱等常规方式时，会使用阿斯塔特重力伞。它以悬浮力场抵消重力、减缓下降。跳跃背包能够将使用者推上空中，重力伞的输出却只够控制下落方向并安全着陆，例如从运输机进行战斗空降。',4:'装备 Mk.X 恐惧型护甲的原铸星际战士也使用重力伞，尤其是掠夺者小队和先锋压制者。'},notes={4:'按原文保留对使用者护甲的归类；不据其他单位资料擅改本篇范围。'},terms=[('Grav Chutes','重力伞')])
save(1341,{2:'抓钩发射器是一种发射攀援钩索的装备，由原铸星际战士掠夺者和侦察兵猎手使用。'},terms=[('Grapnel Launcher','抓钩发射器')])
save(1342,{2:'扫描仪也称多谱扫描仪或鸟卜仪，是帝国用于近距离探测的设备，能侦测运动、肉眼不可见的气体，以及广泛波段的能量信号，例如热量、辐射和载具、士兵释放的大多数能量。',4:'Ultramarine Sergeant Antaro Chronus holding an auspex 手持鸟卜仪的极限战士军士安塔洛·克罗诺斯',7:'它的主要战术用途是发现隐藏的敌军，使己方能够向其开火。手持扫描仪的标准探测距离依型号可为50米、500米或1,500米，但厚度超过50厘米的墙壁及某些屏蔽材料可阻断探测。体积更大的远程鸟卜仪，依制造水平可探测5公里或10公里，并穿透最厚1米的墙壁。地面车载型号可达50公里，机载型号则可达100公里。',9:'星舰上的鸟卜仪甚至可以从星系边缘的曼德维尔点，轻易扫描行星轨道与地表。数据经沉思者和单一任务机仆处理后，以全息投影或影像屏幕呈现。',11:'扫描仪可以是带显示屏的独立手持设备，也能内置于头盔，例如终结者盔甲的头盔。帝国卫队将其所用型号称为勘测仪，星际战士等部队则称之为鸟卜仪。',14:'这种能量扫描装置可提醒使用者：附近藏有敌军，或有敌军即将到来。',17:'思维空间侵入器——瓦努斯刺客使用。',20:'能量扫描仪通过探测能量辐射，定位载具、机器人、运转中的设备和武器等。它不会探测普通生命活动，却会将灵能活动显示为异常强烈的读数。不过，它无法将辐射源与其他能量信号明确区分。',25:'北极星级——恐惧打击小队使用。这种古老而罕见的型号能够提供极其丰富的战场信息，效果近乎有一艘星舰在高空扫描整个地区。'},notes={7:'补回原译遗漏的首句战术用途；five or ten保留两种距离，不改为连续范围。',17:'Noospheric沿Noosphere思维空间统一；设备全名暂译，官方待核。',25:'inloads指输入的信息，不是战略性嵌入。'},terms=[('Scanner','扫描仪'),('Auspex','鸟卜仪'),('Surveyor','勘测仪'),('Augury Scanner','占卜扫描仪'),('Noospheric Interlopers','思维空间侵入器'),('Energy Scanner','能量扫描仪'),('Divinator Class','占卜师级'),('Lodestar Class','北极星级')])
save(1343,{2:'全景观察镜是星际战士百夫长使用的设备，可帮助他们更有效地指引火力。'},terms=[('Omniscope','全景观察镜')])
save(1344,{2:'目标指示器是一种特殊通讯设备，能获取大量有用的战场瞄准数据，并传给同伴，使射击更精准、配合更协调。死亡守望杀戮小队成员、其他阿斯塔特战团的科技战士、破坏者军士，以及帝国卫队的技术祭司机械教士，都可使用。它单独便有实用价值；若接入整队星际战士相互联通的自动感官系统，更能协助他们以精准协调、难以躲避的火力打击敌人。',4:'Dark Angels Devastator Sergeant with a Signum on his backpack 背包装有目标指示器的黑暗天使破坏者军士'},terms=[('Signum','目标指示器')])
save(1345,{2:'追猎者标记是一种肉眼不可见的小型化学标记，只有通过光感瞄准镜、猎感瞄准镜或自动感应目镜才能发现。星际战士可用它标注路线与着陆区，敌军则难以察觉，甚至完全无法发现。'},notes={2:'photo此处修饰sights，不是照片；两种瞄准镜暂译光感、猎感，官译待核。'},terms=[('Stalker Flare','追猎者标记'),('Auto-Sense Goggles','自动感应目镜'),('Preysense Sights','猎感瞄准镜')])
save(1346,{2:'重力照明弹从内置管式发射器射出，用来照亮大片地形。小型火箭发动机将它送上高空，再由类似重力板的低功率重力系统维持悬停。它以极强的化学光照亮约10公里宽的区域，可发出红、白、绿、金或蓝色光。'},terms=[('Grav-flares','重力照明弹')])
save(1347,{2:'光束探照灯是星际战士使用的高功率探照灯，能连续发出短促闪光，使没有眼部防护的敌人目眩失明。其镁质发光元件需要极大能量，因此只有穿着终结者盔甲的星际战士才能使用。'},terms=[('Photon Beam Searchlight','光束探照灯')])
save(1348,{2:'发光信号照明器是一种高亮信标，体积约为标准爆矢弹的一半，具有常亮和频闪两种模式。常亮模式用于标记、照明，可照亮直径5米的区域；频闪模式每分钟闪烁数百次，通常用于求救。与灯组或发光球不同，它是一次性用品，电力耗尽后便会丢弃。'},terms=[('Luminator Signal Flare Capsules','发光信号照明器')])
